/** Evidence needed to authenticate a hardware-backed encryption identity. */
export interface HardwareEvidence {
  /** Raw Intel TDX quote. */
  readonly quote: Uint8Array;
  /** Uncompressed secp256k1 public key advertised by the enclave. */
  readonly signingPublicKey: Uint8Array;
  /** Fresh 32-byte challenge generated by the caller. */
  readonly nonce: Uint8Array;
  /** NVIDIA evidence returned with the attestation. */
  readonly gpuEvidence: unknown;
}

/** Trusted request services and limits owned by the privacy runtime. */
export interface VerificationContext {
  /** Cancellation covering all verifier requests and reads. */
  readonly signal: AbortSignal;
  /** Runtime-owned HTTP implementation. */
  readonly fetch: typeof globalThis.fetch;
  /** Trusted PCCS origin; never taken from attestation content. */
  readonly pccsURL: string;
  /** Trusted NVIDIA attestation endpoint. */
  readonly nrasURL: string;
  /** Maximum bytes accepted from each verification service response. */
  readonly maxEvidenceBytes: number;
  /** Deadline for one service request, within the owning request deadline. */
  readonly verificationTimeoutMs?: number;
}

/** Validated NVIDIA evidence for a fresh challenge. */
export interface NvidiaEvidence {
  readonly nonce: string;
  readonly arch: string;
  readonly evidence_list: readonly {
    readonly certificate: string;
    readonly evidence: string;
    readonly arch?: string;
  }[];
}

/** Authenticated NRAS envelope and individually signed GPU submodules. */
export interface NvidiaTokens {
  readonly overall: string;
  readonly devices: Readonly<Record<string, string>>;
}
